/**
 * A Generic FLC computer to be used in directors that require FLC logic.
 */
class BoeingFlcComputer extends GenericFlcComputer {
    /**
     * Creates an instance of GenericFlcComputer.
     * @param bus The Event Bus.
     * @param performanceData Boeing performance data provider.
     */
    constructor(bus, performanceData) {
        super({ kP: 2, kI: 0, kD: 0, maxOut: 90, minOut: -90 });
        this.performanceData = performanceData;
        //private lastLogTime = 0;
        this.lastCalculationTime = 0;
        this.lastRateLimitedTargetIas = 0;
        this.iasTrimBiasDeg = 0;
        this.standardGravity = UnitType.G_ACCEL.convertTo(1, UnitType.MPS_PER_SEC);
        this.wingArea = UnitType.FOOT_SQ.convertTo(this.performanceData.aircraftFlightModel.wing_area, UnitType.METER_SQ);
        this.flapsFilter = new SimpleMovingAverage(150);
        this.gearPosition = ConsumerSubject.create(null, 0);
        // Constants:
        this.iasError2FpaDivider = 26;
        this.maxIasTargetRate = 1; // Max target IAS adjustment rate in kts/s
        this.iasTrimGain = 0.0006; // Max trim bias increase in deg/s per knot of IAS error
        this.iasTrimDecayRate = 0.01; // Bias decay rate in 1/s when IAS decreases
        this.maxIasTrimBiasDeg = 1.5;
        // Fast simvars:
        this.actAoaDegId = SimVar.GetRegisteredId('INCIDENCE ALPHA', SimVarValueType.Degree, ''); // AoA
        this.actIasKnotsId = SimVar.GetRegisteredId('AIRSPEED INDICATED', SimVarValueType.Knots, ''); // IAS
        this.actAltMeterId = SimVar.GetRegisteredId('PLANE ALTITUDE', SimVarValueType.Meters, '');
        this.actVsMpsId = SimVar.GetRegisteredId('VERTICAL SPEED', SimVarValueType.MetersPerSecond, ''); // ft/s
        this.apSpeedInMachId = SimVar.GetRegisteredId('AUTOPILOT MANAGED SPEED IN MACH', SimVarValueType.Bool, '');
        this.apSelectedMachId = SimVar.GetRegisteredId('AUTOPILOT MACH HOLD VAR', SimVarValueType.Number, '');
        this.weightKgId = SimVar.GetRegisteredId('TOTAL WEIGHT', 'kilogram', '');
        this.bankAngleRadId = SimVar.GetRegisteredId('PLANE BANK DEGREES', SimVarValueType.Radians, ''); // Bank
        this.temperatureId = SimVar.GetRegisteredId('AMBIENT TEMPERATURE', SimVarValueType.Celsius, '');
        this.pressureId = SimVar.GetRegisteredId('AMBIENT PRESSURE', SimVarValueType.HPA, '');
        this.densityId = SimVar.GetRegisteredId('AMBIENT DENSITY', SimVarValueType.KgPerCubicMeter, '');
        this.flapHandleIndexId = SimVar.GetRegisteredId('FLAPS HANDLE INDEX', SimVarValueType.Number, '');
        this.spoilerPosId = SimVar.GetRegisteredId('SPOILERS HANDLE POSITION', SimVarValueType.Number, '');
        this.engineCount = SimVar.GetSimVarValue('NUMBER OF ENGINES', SimVarValueType.Number);
        const sub = bus.getSubscriber();
        this.gearPosition.setConsumer(sub.on('gear_position'));
    }
    /**
     * Limit the slope the IAS target input signal has over time.
     * @param newTargetIas new target IAS.
     * @param dt time delta since last computation
     * @returns rate limited target IAS.
     */
    getRateLimitedTargetIas(newTargetIas, dt) {
        const rate = (newTargetIas - this.lastRateLimitedTargetIas) / dt;
        if (rate > this.maxIasTargetRate) {
            this.lastRateLimitedTargetIas += dt * this.maxIasTargetRate;
        }
        else if (rate < -this.maxIasTargetRate) {
            this.lastRateLimitedTargetIas -= dt * this.maxIasTargetRate;
        }
        else {
            this.lastRateLimitedTargetIas = newTargetIas;
        }
        return this.lastRateLimitedTargetIas;
    }
    /**
     * Gets a desired pitch when airborne to maintain a given speed.
     * @returns The desired pitch angle.
     */
    getDesiredPitch() {
        const time = performance.now() / 1000;
        const dt = time - this.lastCalculationTime;
        if ((this.lastCalculationTime === 0) || (dt > 3)) {
            // Reset lastRateLimitedTargetIas if the FLC was off for more than 3 seconds:
            this.lastCalculationTime = time;
            this.lastRateLimitedTargetIas = this._targetIas;
            this.iasTrimBiasDeg = 0;
            return SimVar.GetSimVarValue('PLANE PITCH DEGREES', SimVarValueType.Degree);
        }
        this.lastCalculationTime = time;
        // Get the required data:
        const actAoaDeg = SimVar.GetSimVarValueFastReg(this.actAoaDegId);
        const actIasKnots = SimVar.GetSimVarValueFastReg(this.actIasKnotsId);
        const actAltMeter = SimVar.GetSimVarValueFastReg(this.actAltMeterId);
        const actVsMps = SimVar.GetSimVarValueFastReg(this.actVsMpsId);
        const actIasMps = UnitType.KNOT.convertTo(actIasKnots, UnitType.MPS);
        const apSpeedInMach = SimVar.GetSimVarValueFastReg(this.apSpeedInMachId);
        const apSelectedMach = SimVar.GetSimVarValueFastReg(this.apSelectedMachId);
        const weightKg = SimVar.GetSimVarValueFastReg(this.weightKgId);
        const bankAngleRad = SimVar.GetSimVarValueFastReg(this.bankAngleRadId);
        const temperature = SimVar.GetSimVarValueFastReg(this.temperatureId);
        const pressure = SimVar.GetSimVarValueFastReg(this.pressureId);
        const density = SimVar.GetSimVarValueFastReg(this.densityId);
        const flapHandleIndex = SimVar.GetSimVarValueFastReg(this.flapHandleIndexId);
        const spoilerPos = SimVar.GetSimVarValueFastReg(this.spoilerPosId);
        const iasTarget = this.getRateLimitedTargetIas(this._targetIas, dt);
        // During climbs or descends at steady IAS or MACH, there is a constant acceleration/deceleration bias.
        // Therefore, to keep IAS or MACH constant, the aircraft needs to be held constant at a non-zero forward acceleration, which is
        // considered the Z acceleration bias.
        // It is calculated as the TAS difference between the altitude in one second and current alt:
        const accZBiasMpss = apSpeedInMach ?
            AeroMath.machToTasIsa(apSelectedMach, actAltMeter + actVsMps) - AeroMath.machToTasIsa(apSelectedMach, actAltMeter) :
            AeroMath.casToTasIsa(actIasMps, actAltMeter + actVsMps) - AeroMath.casToTasIsa(actIasMps, actAltMeter);
        // New approach with reference model for drag:
        // Using a calculated drag for target IAS rather than using observed acceleration results in smoother climbs and descents, which
        // are less prone to speed variations.
        // Calculate Cl for the unaccelerated flight at current alt, temp and target IAS:
        const targetTas = AeroMath.casToTas(UnitType.KNOT.convertTo(iasTarget, UnitType.MPS), pressure, temperature);
        const Cl = AeroMath.liftCoefficient(weightKg * 9.81 / Math.cos(bankAngleRad), this.wingArea, density, targetTas);
        // Create smooth flaps Cd's between flap handle positions. For the transition between flap positions, we simply assume a
        // steady movement over several seconds:
        const configCount = this.performanceData.getNumberOfConfigurations();
        const continousFlapsIndex = this.flapsFilter.getAverage(flapHandleIndex);
        const nextLowerFlapsIndex = MathUtils.clamp(Math.floor(continousFlapsIndex), 0, configCount - 1);
        const nextHigherFlapsIndex = MathUtils.clamp(Math.ceil(continousFlapsIndex), 0, configCount - 1);
        let Cd = 0.001; // Sideslip and controls surfaces seem to contribute constantly around 0.001 as a baseline to Cd
        if (nextLowerFlapsIndex < nextHigherFlapsIndex) {
            const CdLower = this.performanceData.calculateCD(Cl, nextLowerFlapsIndex, this.gearPosition.get(), spoilerPos);
            const CdHigher = this.performanceData.calculateCD(Cl, nextHigherFlapsIndex, this.gearPosition.get(), spoilerPos);
            const CdRatio = continousFlapsIndex - nextLowerFlapsIndex;
            Cd += CdRatio * CdHigher + (1 - CdRatio) * CdLower;
        }
        else {
            Cd += this.performanceData.calculateCD(Cl, nextLowerFlapsIndex, this.gearPosition.get(), spoilerPos);
        }
        const dragN = Cd * density * targetTas * targetTas * this.wingArea / 2;
        let thrustN = 0;
        for (let i = 1; i < this.engineCount + 1; i++) {
            thrustN += SimVar.GetSimVarValue('TURB ENG JET THRUST:' + i, 'pounds');
        }
        thrustN = UnitType.POUND_FORCE.convertTo(thrustN, UnitType.NEWTON); // Get thrust in [N]
        const excessThrustN = thrustN - dragN - accZBiasMpss * weightKg; // [N]
        const zeroAccFpaDeg = UnitType.RADIAN.convertTo(Math.asin(excessThrustN / (weightKg * this.standardGravity)), UnitType.DEGREE);
        // For the correction of an IAS error, we calculate an FPA correction:
        // To get smooth FPA changes when changing the IAS target, we apply a change rate limitation to target IAS.
        // During climbs, at max apply target fpa +90% to bleed off speed and -90% to pick up speed
        // During descends, at max apply apply target fpa +90% to bleed of speed or -90% to pick up speed
        // IAS error is corrected with a P controller and a slow trim bias to remove steady-state error.
        const iasError = iasTarget - actIasKnots;
        const iasErrorPGain = iasError / this.iasError2FpaDivider;
        const fpaCorrectionFactor = MathUtils.clamp(1 + (this._climbMode ? -iasErrorPGain : iasErrorPGain), 0.1, 1.9);
        const signedIasError = this._climbMode ? -iasError : iasError;
        this.iasTrimBiasDeg = MathUtils.clamp(this.iasTrimBiasDeg + (signedIasError * this.iasTrimGain - this.iasTrimBiasDeg * this.iasTrimDecayRate) * dt, -this.maxIasTrimBiasDeg, this.maxIasTrimBiasDeg);
        const targetFpaDeg = zeroAccFpaDeg * fpaCorrectionFactor + this.iasTrimBiasDeg;
        // Targetpitch follows as usual:
        const targetPitchDeg = this._climbMode ? Math.max(targetFpaDeg + actAoaDeg, actAoaDeg) : Math.min(targetFpaDeg + actAoaDeg, actAoaDeg);
        // Keep for testing and data acquisition:
        // const actVsFpm = SimVar.GetSimVarValue('VERTICAL SPEED', SimVarValueType.FPM);
        // if (time > this.lastLogTime + 0.5) {
        //   console.log(';targetPitch;' + targetPitchDeg.toFixed(4) + ';iastrg;' + iasTarget +
        //     ';ias;' + actIasKnots.toFixed(1) + ';vs;' + actVsFpm.toFixed(0) + ';contFlaps;' + continousFlapsIndex.toFixed(3) +
        //     ';fpaCorr;' + fpaCorrectionFactor.toFixed(2) + ';targetFpa;' + targetFpaDeg.toFixed(4) + ';zeroAccFpa;' + zeroAccFpaDeg);
        //   this.lastLogTime = time;
        // }
        // SimVar.SetSimVarValue('L:FPACORRFACTOR', SimVarValueType.Number, fpaCorrectionFactor);
        // SimVar.SetSimVarValue('L:ZEROACCPFA', SimVarValueType.Number, zeroAccFpaDeg);
        // SimVar.SetSimVarValue('L:IASTRGT', SimVarValueType.Number, this._targetIas);
        // SimVar.SetSimVarValue('L:SMOOTHEDIASTRGT', SimVarValueType.Number, iasTarget);
        return targetPitchDeg;
    }
}

