BoeingAPUtils.GS_DEADBAND_NEAR_FT = 2;
BoeingAPUtils.GS_DEADBAND_FAR_FT = 5;
BoeingAPUtils.GS_MAX_CORRECTION_NEAR_FPM = 650;
BoeingAPUtils.GS_MAX_CORRECTION_FAR_FPM = 900;
BoeingAPUtils.GS_CAPTURE_TIME = 9;
BoeingAPUtils.GS_MAX_CLIMB_NEAR_DISTANCE_M = 600;
BoeingAPUtils.GS_MAX_CLIMB_FAR_DISTANCE_M = 3000;
BoeingAPUtils.GS_MAX_CLIMB_NEAR_FPM = 0;
