/**
 * Boeing FCU HEvent manager
 */
class BoeingFcuHEventsManager {
    /**
     * Ctor
     * @param bus The event bus
     * @param onFcuEvent Callback to AP State Manager
     * @param hEventPrefixes event prefixes to check for
     */
    constructor(bus, onFcuEvent, hEventPrefixes) {
        this.bus = bus;
        this.onFcuEvent = onFcuEvent;
        this.hEventPattern = new RegExp(`^(?:${hEventPrefixes.join('|')})(.+)`);
        this.bus.getSubscriber().on('hEvent').handle(event => {
            const match = event.match(this.hEventPattern);
            if (match !== null) {
                this.handleEvent(match[1]);
            }
        });
    }
    /**
     * Handles the event.
     * @param event The name of the event.
     */
    handleEvent(event) {
        switch (event) {
            case 'AP_LNAV': {
                SimVar.SetSimVarValue('K:AP_NAV1_HOLD', SimVarValueType.Bool, 1);
                break;
            }
            case 'AP_HEADING_SEL': {
                SimVar.SetSimVarValue('K:AP_HDG_HOLD_ON', SimVarValueType.Bool, 1);
                break;
            }
            case 'AP_FLCH': {
                SimVar.SetSimVarValue('K:FLIGHT_LEVEL_CHANGE_ON', SimVarValueType.Bool, 1);
                break;
            }
            case 'VS':
            case 'AP_VSPEED': {
                SimVar.SetSimVarValue('K:AP_VS_ON', SimVarValueType.Bool, 1);
                break;
            }
            case 'ALT_HOLD':
            case 'AP_ALT_HOLD': {
                SimVar.SetSimVarValue('K:AP_ALT_HOLD_ON', SimVarValueType.Bool, 1);
                break;
            }
            case 'AP_LOC':
            case 'VOR_LOC': {
                SimVar.SetSimVarValue('K:AP_LOC_HOLD', SimVarValueType.Bool, 1);
                break;
            }
            case 'AP_APR':
            case 'APP': {
                SimVar.SetSimVarValue('K:AP_APR_HOLD', SimVarValueType.Bool, 1);
                break;
            }
            case 'AP_HEADING_SELECT':
            case 'HDG_SEL': {
                SimVar.SetSimVarValue('K:AP_HDG_HOLD', SimVarValueType.Bool, 1);
                break;
            }
            case 'CWS': {
                // FIXME implement CWS
                // eslint-disable-next-line no-console
                console.log(event);
                break;
            }
            default: {
                this.onFcuEvent(event);
                break;
            }
        }
    }
}

