        super(bus, screen, fms, renderCallback);
        this.showBottomDashedLine = showBottomDashedLine;
        this.navDatesOverlap = navDatesOverlap;
        this.databaseDatesFormatter = AiracCycleFormatter.create(`{eff({MON}{dd})}{${this.navDatesOverlap ? 'exp' : 'expMinus'}({MON}{dd})}/{eff({YY})}`);
        this.databaseSerialFormatter = AiracCycleFormatter.create('WT10{YYCC}01');
        this.IndexLink = PageLinkField.createLink(this, '<INDEX', '/init-ref');
